package java.util.concurrent;
import java.util.*;
public class PriorityBlockingQueue<E> extends AbstractQueue<E> implements BlockingQueue<E>,java.io.Serializable {
 private final PriorityQueue<E> q; public PriorityBlockingQueue(){q=new PriorityQueue<E>();} public PriorityBlockingQueue(int n){q=new PriorityQueue<E>(n);} public PriorityBlockingQueue(int n,Comparator<? super E> c){q=new PriorityQueue<E>(n,c);} public PriorityBlockingQueue(Collection<? extends E> c){q=new PriorityQueue<E>(c);} public Comparator<? super E> comparator(){return q.comparator();} public int size(){return q.size();} public Iterator<E> iterator(){return q.iterator();} public boolean offer(E e){return q.offer(e);} public E poll(){return q.poll();} public E peek(){return q.peek();} public void put(E e){offer(e);} public boolean offer(E e,long n,TimeUnit u){if(u==null)throw new NullPointerException();return offer(e);} public E take()throws InterruptedException{E e=poll();if(e==null){java.lang.VMThread.runPending();e=poll();}return e;} public E poll(long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();return take();} public int remainingCapacity(){return Integer.MAX_VALUE;} public boolean remove(Object o){return q.remove(o);} public void clear(){q.clear();} public int drainTo(Collection<? super E> c){return drainTo(c,Integer.MAX_VALUE);} public int drainTo(Collection<? super E> c,int max){if(c==null)throw new NullPointerException();if(c==this)throw new IllegalArgumentException();int n=0;while(n<max&&!q.isEmpty()){c.add(q.peek());q.poll();n++;}return n;}
}